"use client";

import type { CSSProperties, ReactNode } from "react";
import { Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

export interface ZoomThroughProps {
  /** The element the camera flies into. Falls back to a browser-style dashboard card. */
  children?: ReactNode;
  /** Final scale value at the end of the duration. */
  targetScale?: number;
  /** CSS transform-origin — the point the camera zooms through. */
  transformOrigin?: string;
  /** Background color visible around the content during the zoom. */
  background?: string;
  /** Fade the content out over the last third so the next scene can take over. */
  fadeOut?: boolean;
  /** Playback-rate multiplier. */
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif";

function Bar({
  width,
  height = 8,
  color = "#E4E7EC",
  radius = 4,
  style,
}: {
  width: number | string;
  height?: number;
  color?: string;
  radius?: number;
  style?: CSSProperties;
}) {
  return (
    <div
      style={{
        width,
        height,
        borderRadius: radius,
        background: color,
        ...style,
      }}
    />
  );
}

function StatCard({
  label,
  value,
  delta,
}: {
  label: string;
  value: string;
  delta: string;
}) {
  return (
    <div
      style={{
        flex: 1,
        background: "#FFFFFF",
        border: "1px solid #E4E7EC",
        borderRadius: 8,
        padding: "10px 12px",
        display: "flex",
        flexDirection: "column",
        gap: 4,
      }}
    >
      <div style={{ fontSize: 9, color: "#667085", fontWeight: 500 }}>
        {label}
      </div>
      <div
        style={{
          fontSize: 16,
          color: "#101828",
          fontWeight: 600,
          letterSpacing: "-0.01em",
        }}
      >
        {value}
      </div>
      <div style={{ fontSize: 8, color: "#12B76A", fontWeight: 500 }}>
        {delta}
      </div>
    </div>
  );
}

/**
 * Browser-frame card wrapping a compact dashboard — the surface the
 * default demo zooms through.
 */
function DefaultContent() {
  const chartHeights = [22, 34, 28, 46, 38, 58, 50, 70, 62, 82, 74, 92];
  return (
    <div
      style={{
        width: 640,
        height: 400,
        borderRadius: 10,
        background: "#FFFFFF",
        border: "1px solid #E4E7EC",
        boxShadow:
          "0 1px 2px rgba(16, 24, 40, 0.05), 0 12px 32px rgba(16, 24, 40, 0.08)",
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        fontFamily: FONT_FAMILY,
      }}
    >
      {/* Browser chrome */}
      <div
        style={{
          height: 40,
          flexShrink: 0,
          display: "flex",
          alignItems: "center",
          gap: 12,
          padding: "0 14px",
          background: "#FAFAFA",
          borderBottom: "1px solid #E4E7EC",
        }}
      >
        <div style={{ display: "flex", gap: 6 }}>
          {[0, 1, 2].map((i) => (
            <div
              key={i}
              style={{
                width: 9,
                height: 9,
                borderRadius: "50%",
                background: "#E4E7EC",
              }}
            />
          ))}
        </div>
        <div
          style={{
            flex: 1,
            maxWidth: 300,
            margin: "0 auto",
            height: 22,
            borderRadius: 6,
            background: "#FFFFFF",
            border: "1px solid #E4E7EC",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 10,
            color: "#667085",
          }}
        >
          acme.com/dashboard
        </div>
        <div style={{ width: 33 }} />
      </div>

      {/* Dashboard body */}
      <div style={{ flex: 1, display: "flex", minHeight: 0 }}>
        {/* Sidebar */}
        <div
          style={{
            width: 132,
            flexShrink: 0,
            borderRight: "1px solid #E4E7EC",
            background: "#FAFAFA",
            padding: 14,
            display: "flex",
            flexDirection: "column",
            gap: 12,
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            {/* Accent glyph */}
            <div
              style={{
                width: 20,
                height: 20,
                borderRadius: 6,
                background: "#266DF0",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: "#FFFFFF",
                fontSize: 11,
                fontWeight: 700,
                letterSpacing: "-0.02em",
              }}
            >
              A
            </div>
            <div
              style={{
                fontSize: 11,
                fontWeight: 600,
                color: "#101828",
                letterSpacing: "-0.01em",
              }}
            >
              Acme
            </div>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <Bar width="86%" color="#266DF0" style={{ opacity: 0.9 }} />
            <Bar width="70%" />
            <Bar width="78%" />
            <Bar width="58%" />
            <Bar width="66%" />
          </div>
        </div>

        {/* Main area */}
        <div
          style={{
            flex: 1,
            padding: 16,
            display: "flex",
            flexDirection: "column",
            gap: 12,
            background: "#FFFFFF",
            minWidth: 0,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <div
              style={{
                fontSize: 14,
                fontWeight: 600,
                color: "#101828",
                letterSpacing: "-0.01em",
              }}
            >
              Overview
            </div>
            <div
              style={{
                fontSize: 9,
                fontWeight: 500,
                color: "#FFFFFF",
                background: "#266DF0",
                borderRadius: 6,
                padding: "4px 10px",
              }}
            >
              New report
            </div>
          </div>
          <div style={{ display: "flex", gap: 10 }}>
            <StatCard label="Revenue" value="$128.4k" delta="+12.4%" />
            <StatCard label="Active users" value="8,241" delta="+6.1%" />
            <StatCard label="Conversion" value="3.9%" delta="+0.8%" />
          </div>
          <div
            style={{
              flex: 1,
              border: "1px solid #E4E7EC",
              borderRadius: 8,
              padding: "12px 14px",
              display: "flex",
              alignItems: "flex-end",
              gap: 8,
              minHeight: 0,
            }}
          >
            {chartHeights.map((h, i) => (
              <div
                key={h}
                style={{
                  flex: 1,
                  height: `${h}%`,
                  borderRadius: 3,
                  background:
                    i === chartHeights.length - 1 ? "#266DF0" : "#E4E7EC",
                }}
              />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Scale-into-content camera move: fly through a framed element until it is
 * full-bleed — the "enter the product" beat after a hook title.
 */
export function ZoomThrough({
  children,
  targetScale = 9,
  transformOrigin = "50% 55%",
  background = "#FAFAFA",
  fadeOut = true,
  speed = 1,
  className,
}: ZoomThroughProps) {
  const frame = useCurrentFrame() * speed;
  const { durationInFrames } = useVideoConfig();

  const scale = interpolate(frame, [0, durationInFrames], [1, targetScale], {
    extrapolateRight: "clamp",
    // Ease-out with a long tail: a fast punch through the browser frame
    // that settles as the dashboard goes full-bleed.
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });

  const opacity = fadeOut
    ? interpolate(
        frame,
        [0, durationInFrames * 0.7, durationInFrames],
        [1, 1, 0],
        { extrapolateRight: "clamp" },
      )
    : 1;

  const content = children ?? <DefaultContent />;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        background,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          transform: `scale(${scale})`,
          transformOrigin,
          opacity,
          willChange: "transform, opacity",
        }}
      >
        {content}
      </div>
    </div>
  );
}
